function validate([books]) {
  if (!Array.isArray(books) || books.length < 1 || books.length > 100000) return 'books needs 1 to 10^5 shelves.';
  if (!books.every(v => Number.isInteger(v) && v >= 0 && v <= 100000)) return 'Each shelf holds an integer from 0 to 10^5 books.';
  return null;
}

