function maximumBooks(books) {
  const n = books.length;
  const dp = new Array(n).fill(0);
  const stack = [];
  let best = 0;

  for (let i = 0; i < n; i++) {
    while (stack.length > 0 && books[stack.at(-1)] - stack.at(-1) >= books[i] - i) {
      stack.pop();
    }
    const prev = stack.length > 0 ? stack.at(-1) : -1;
    const count = Math.min(books[i], i - prev);
    dp[i] = count * books[i] - (count * (count - 1)) / 2;
    if (prev >= 0) {
      dp[i] += dp[prev];
    }
    stack.push(i);
    best = Math.max(best, dp[i]);
  }
  return best;
}

