function maximumBooks(books) {
  let best = 0;
  for (let r = 0; r < books.length; r++) {
    // Ending at shelf r, take everything there and as much as allowed on each shelf to the left.
    let take = books[r];
    let total = take;
    for (let k = r - 1; k >= 0 && take > 1; k--) {
      take = Math.min(books[k], take - 1);
      total += take;
    }
    best = Math.max(best, total);
  }
  return best;
}

