  if (size === 'small') {
    const n = int(1, 9);
    const top = [0, 2, 5, 12][int(0, 3)];
    const climb = rand() < 0.3;
    return [Array.from({ length: n }, (_, i) => climb ? Math.min(12, i + int(0, 2)) : int(0, top))];
  }
  const n = 2000;
  const shape = int(0, 2);
  if (shape === 0) return [Array.from({ length: n }, () => int(0, 100000))];
  if (shape === 1) return [Array.from({ length: n }, (_, i) => Math.max(0, Math.min(100000, 50 * i - int(0, 3000))))];
  return [Array.from({ length: n }, (_, i) => Math.min(100000, i + int(0, 40)))];
}
